      "id": "voyagers-24-hour-light-time-costs-two-days-per-repair",
      "title": "A Light-Day to Voyager Turns Every Repair Into a Two-Day Loop",
      "kicker": "SCIENCE // CONCEPTS",
      "category": "science",
      "subtopic": "concepts",
      "author": "Dr. Aris Thorne",
      "role": "Staff writer",
